// Frozen controlled bundle declaration generated by the existing programc_test
// bundleRequest constructor, never a provider capture or candidate-authored grant.
// The opaque expectation is created separately by NewGroupingBundleExpectation.
const controlledTypedBundleFixtureV2 = ""

// TEST1e12 is existing synthetic fixtureV2/sealV2/initialize authority ONLY.
func controlledTypedOwnerV2(t *testing.T) (*PrivateTypedBundleOwnerV2, harnessV2) {
	return controlledTypedChangedV2(t, nil)
}
func controlledTypedChangedV2(t *testing.T, change func(*authorizationV2)) (*PrivateTypedBundleOwnerV2, harnessV2) {
	t.Helper()
	x := harnessTestV2(t, func(a *authorizationV2) {
		a.Ceiling = countersFromV2([14]uint64{1e12, 1e12, 1e12, 1e12, 1e12, 1e12, 1e12, 1e12, 1e12, 1e12, 1e12, 1e12, 1e12, 1e12})
		a.MaxTranche = a.Ceiling
		a.MaxWindows = 100
		a.MaxWindowNS = uint64(60 * time.Second)
		a.Expires = 4102444800000000000
		if change != nil {
			change(a)
		}
	})
	o, e := OpenPrivateTypedBundleOwnerV2(context.Background(), x.k.root, sealTestV2(t, &x.j), x.h.Identity, PrivateManagedInputVerificationV2{4096, 64 << 20, 16384})
	if e != nil {
		t.Fatal(e)
	}
	return o, x
}
func typedFixtureBundleV2(t *testing.T, alternate bool) pc.GroupingCaseBundlePrivate {
	t.Helper()
	z, e := base64.StdEncoding.DecodeString(controlledTypedBundleFixtureV2)
	if e != nil {
		t.Fatal(e)
	}
	gz, e := gzip.NewReader(bytes.NewReader(z))
	if e != nil {
		t.Fatal(e)
	}
	defer gz.Close()
	raw, e := io.ReadAll(io.LimitReader(gz, pc.GroupingCaseBundleMaxBytesPrivate+1))
	if e != nil {
		t.Fatal(e)
	}
	var request pc.GroupingCaseBundleRequestPrivate
	if e = json.Unmarshal(raw, &request); e != nil {
		t.Fatal(e)
	}
	if alternate {
		request.BatchID += "-independent-alternate"
	}
	b, e := pc.NewGroupingCaseBundlePrivate(request)
	if e != nil {
		t.Fatal(e)
	}
	return b
}
func typedBindingV2(t *testing.T, head string) PrivateTypedBundleBindingV2 {
	t.Helper()
	b := typedFixtureBundleV2(t, false)
	expected, e := pc.NewGroupingBundleExpectationPrivate(b)
	if e != nil {
		t.Fatal(e)
	}
	return PrivateTypedBundleBindingV2{Expected: expected, Candidate: b.CanonicalBytes(), Attempt: hashLabelV2(t.Name()), Head: head, Deadline: time.Now().Add(12 * time.Second)}
}

func typedHeadV2(t *testing.T, o *PrivateTypedBundleOwnerV2, x harnessV2) resourceHeadV2 {
	t.Helper()
	h, e := x.k.reopen(context.Background(), x.j, o.limits)
	if e != nil {
		t.Fatal(e)
	}
	return h
}
func typedFreshRootV2(t *testing.T, x harnessV2) *publication.Root {
	t.Helper()
	path := x.k.root.Path()
	if e := x.k.root.Close(); e != nil {
		t.Fatal(e)
	}
	root, e := publication.OpenRoot(path)
	if e != nil {
		t.Fatal(e)
	}
	t.Cleanup(func() { root.Close() })
	return root
}
func typedAssertRefusedV2(t *testing.T, o *PrivateTypedBundleOwnerV2, op PrivateTypedBundleOperationV2, q PrivateTypedBundleBindingV2, ctx context.Context) {
	t.Helper()
	b, obs, f := o.Execute(ctx, op, q)
	if b != nil || f == nil || obs.Imported || obs.Executed || obs.Checked {
		t.Fatalf("ASSERT_BOUND_ONE_SHOT: bytes=%d failure=%v", len(b), f)
	}
}

func TestPrivateTypedOwnerFixtureV2(t *testing.T) {
	o, x := controlledTypedOwnerV2(t)
	if o == nil {
		t.Fatal("ASSERT_EXISTING_KERNEL_BASELINE")
	}
	if out := os.Getenv("TYPED_OWNER_FIXTURE_OUT"); out != "" {
		files := map[string][]byte{}
		for _, s := range []string{initialSelectorV2(x.j), currentSelectorV2(x.j), recordSelectorV2(headsNamespaceV2, x.h.Identity), x.h.AuthorizationSelector} {
			raw, e := x.k.root.ReadSelector(s, headLimitV2)
			if e != nil {
				t.Fatal(e)
			}
			files[s] = raw
		}
		b, e := json.Marshal(struct {
			Job   []byte
			Head  string
			Files map[string][]byte
		}{sealTestV2(t, &x.j), x.h.Identity, files})
		if e != nil {
			t.Fatal(e)
		}
		if e = os.WriteFile(out, b, 0600); e != nil {
			t.Fatal(e)
		}
	}
	t.Log("ASSERT_EXISTING_KERNEL_BASELINE: PASS TEST1e12")
}

func TestPrivateTypedOwnerBoundsV2(t *testing.T) {
	_, x := controlledTypedOwnerV2(t)
	for _, l := range []PrivateManagedInputVerificationV2{{}, {4097, 64 << 20, 16384}, {4096, 0, 16384}, {4096, 64 << 20, 0}} {
		if _, e := OpenPrivateTypedBundleOwnerV2(context.Background(), x.k.root, sealTestV2(t, &x.j), x.h.Identity, l); e == nil {
			t.Fatal("ASSERT_FINITE_VERIFICATION")
		}
	}
	for _, d := range []time.Time{{}, time.Now().Add(-time.Second), time.Now().Add(61 * time.Second)} {
		if _, e := privateTypedBundleChargeV2(time.Now(), d); e == nil {
			t.Fatal("ASSERT_FINITE_CHARGE_WINDOW")
		}
	}
	c, e := privateTypedBundleChargeV2(time.Unix(10, 0), time.Unix(70, 0))
	if e != nil {
		t.Fatal(e)
	}
	if c.ProviderRequests != 0 || c.ProviderMessages != 0 || c.WireBytes != uint64((128<<20)+(64<<10)+3) || c.Work == 0 {
		t.Fatalf("ASSERT_CLOSED_VECTOR: %+v", c)
	}
	t.Logf("ASSERT_CLOSED_VECTOR: %+v", c)
}
func TestPrivateTypedOwnerAdmissionV2(t *testing.T) {
	for _, name := range []string{"nil-owner", "cancelled", "zero-expectation", "nil-candidate", "large-candidate", "invalid-attempt", "wrong-head", "zero-deadline", "expired", "overlong", "exhausted", "expired-grant"} {
		t.Run(name, func(t *testing.T) {
			change := func(a *authorizationV2) {
				if name == "exhausted" {
					a.Ceiling.Calls = 0
					a.MaxTranche.Calls = 0
				}
				if name == "expired-grant" {
					a.Expires = 100
				}
			}
			o, x := controlledTypedChangedV2(t, change)
			q := typedBindingV2(t, x.h.Identity)
			ctx := context.Background()
			switch name {
			case "nil-owner":
				o = nil
			case "cancelled":
				c, cancel := context.WithCancel(ctx)
				cancel()
				ctx = c
			case "zero-expectation":
				q.Expected = pc.GroupingBundleExpectationPrivate{}
			case "nil-candidate":
				q.Candidate = nil
			case "large-candidate":
				q.Candidate = make([]byte, pc.GroupingCaseBundleMaxBytesPrivate+1)
			case "invalid-attempt":
				q.Attempt = "unknown"
			case "wrong-head":
				q.Head = hashLabelV2("wrong")
			case "zero-deadline":
				q.Deadline = time.Time{}
			case "expired":
				q.Deadline = time.Now().Add(-time.Second)
			case "overlong":
				q.Deadline = time.Now().Add(61 * time.Second)
			}
			op, e := o.Reserve(ctx, q)
			if e == nil || op.state != nil {
				t.Fatal("ASSERT_ADMISSION_NO_PERMISSION")
			}
			typedAssertRefusedV2(t, o, op, q, context.Background())
		})
	}
}
func TestPrivateTypedOwnerBindingV2(t *testing.T) {
	for _, name := range []string{"bytes", "length", "expectation", "attempt", "head", "deadline", "earlier-deadline", "foreign-owner", "nil-context", "cancelled", "stale-selected-head", "expired"} {
		t.Run(name, func(t *testing.T) {
			o, x := controlledTypedOwnerV2(t)
			q := typedBindingV2(t, x.h.Identity)
			if name == "expired" {
				q.Deadline = time.Now().Add(200 * time.Millisecond)
			}
			op, e := o.Reserve(context.Background(), q)
			if e != nil {
				t.Fatal(e)
			}
			bad := q
			ctx := context.Background()
			target := o
			switch name {
			case "bytes":
				bad.Candidate = bytes.Clone(q.Candidate)
				bad.Candidate[len(bad.Candidate)-2] ^= 1
			case "length":
				bad.Candidate = append(bytes.Clone(q.Candidate), ' ')
			case "expectation":
				bad.Expected, _ = pc.NewGroupingBundleExpectationPrivate(typedFixtureBundleV2(t, true))
			case "attempt":
				bad.Attempt = hashLabelV2("different")
			case "head":
				bad.Head = hashLabelV2("different")
			case "deadline":
				bad.Deadline = bad.Deadline.Add(time.Second)
			case "earlier-deadline":
				bad.Deadline = bad.Deadline.Add(-time.Second)
			case "foreign-owner":
				target, _ = controlledTypedOwnerV2(t)
			case "nil-context":
				ctx = nil
			case "cancelled":
				c, cancel := context.WithCancel(ctx)
				cancel()
				ctx = c
			case "expired":
				time.Sleep(time.Until(q.Deadline) + time.Millisecond)
			case "stale-selected-head":
				_, e = x.k.observe(context.Background(), x.j, op.state.head, q.Attempt, "INDETERMINATE", time.Now().UnixNano(), o.limits)
				if e != nil {
					t.Fatal(e)
				}
			}
			typedAssertRefusedV2(t, target, op, bad, ctx)
			typedAssertRefusedV2(t, o, op, q, context.Background())
			t.Log("ASSERT_BOUND_ONE_SHOT: PASS")
		})
	}
}

// Real CAS faults at the existing instance-local seam; never a substituted worker.
func typedCASFaultV2(o *PrivateTypedBundleOwnerV2, event string, committed bool, delay time.Time) {
	o.k.cas = func(ctx context.Context, r *publication.Root, s string, p publication.BoundFilePredecessor, b []byte, v func([]byte) error) (*publication.CompareAndReplaceReceipt, error) {
		var h resourceHeadV2
		if parseV2(b, &h) != nil {
			return nil, errors.New("bad test CAS")
		}
		if h.Event == event {
			if !delay.IsZero() {
				time.Sleep(time.Until(delay) + time.Millisecond)
			}
			if !committed {
				return nil, errors.New("controlled uncommitted error")
			}
			receipt, e := publication.CompareAndReplaceBoundFile(ctx, r, s, p, b, v)
			if e != nil {
				return receipt, e
			}
			return receipt, errors.New("controlled committed plus error")
		}
		return publication.CompareAndReplaceBoundFile(ctx, r, s, p, b, v)
	}
}
func TestPrivateTypedOwnerReserveUncertainV2(t *testing.T) {
	o, x := controlledTypedOwnerV2(t)
	q := typedBindingV2(t, x.h.Identity)
	typedCASFaultV2(o, "RESERVE", true, time.Time{})
	op, e := o.Reserve(context.Background(), q)
	if e == nil || op.state != nil {
		t.Fatal("ASSERT_RESERVE_ERROR_ZERO_PERMISSION")
	}
	typedAssertRefusedV2(t, o, op, q, context.Background())
	h := typedHeadV2(t, o, x)
	if h.Disposition != "PENDING" || h.Charged.Calls == 0 || !o.uncertain {
		t.Fatalf("ASSERT_RESERVE_ERROR_PENDING_NO_EXECUTION: %+v", h)
	}
	root := typedFreshRootV2(t, x)
	if _, e = OpenPrivateTypedBundleOwnerV2(context.Background(), root, sealTestV2(t, &x.j), h.Identity, PrivateManagedInputVerificationV2{4096, 64 << 20, 16384}); e == nil {
		t.Fatal("ASSERT_PENDING_REOPEN_REFUSED")
	}
	t.Log("ASSERT_RESERVE_ERROR_PENDING_NO_EXECUTION: PASS")
}
func TestPrivateTypedOwnerObserveFaultV2(t *testing.T) {
	for _, mode := range []string{"committed", "uncommitted", "late"} {
		t.Run(mode, func(t *testing.T) {
			o, x := controlledTypedOwnerV2(t)
			q := typedBindingV2(t, x.h.Identity)
			if mode == "late" {
				q.Deadline = time.Now().Add(2 * time.Second)
			}
			op, e := o.Reserve(context.Background(), q)
			if e != nil {
				t.Fatal(e)
			}
			delay := time.Time{}
			if mode == "late" {
				delay = q.Deadline
			}
			typedCASFaultV2(o, "OBSERVE", mode == "committed", delay)
			report, obs, failed := o.Execute(context.Background(), op, q)
			if report != nil || failed == nil || !o.uncertain || !obs.Checked {
				t.Fatalf("ASSERT_OBSERVE_CONFIRMATION_BEFORE_RELEASE: bytes=%d failure=%v uncertain=%v checked=%v", len(report), failed, o.uncertain, obs.Checked)
			}
			h := typedHeadV2(t, o, x)
			if h.Charged.Calls == 0 || h.Windows != 1 {
				t.Fatal("ASSERT_FULL_CHARGE_RETAINED")
			}
			q2 := q
			q2.Head = h.Identity
			q2.Attempt = hashLabelV2("fresh-attempt")
			q2.Deadline = time.Now().Add(12 * time.Second)
			if _, e = o.Reserve(context.Background(), q2); e == nil {
				t.Fatal("ASSERT_UNCERTAIN_OWNER_STOP")
			}
			typedAssertRefusedV2(t, o, op, q, context.Background())
			root := typedFreshRootV2(t, x)
			reopen := func(head string) (*PrivateTypedBundleOwnerV2, error) {
				return OpenPrivateTypedBundleOwnerV2(context.Background(), root, sealTestV2(t, &x.j), head, PrivateManagedInputVerificationV2{4096, 64 << 20, 16384})
			}
			if _, e = reopen(hashLabelV2("wrong-selected-head")); e == nil {
				t.Fatal("ASSERT_WRONG_SELECTED_HEAD_REFUSED")
			}
			next, e := reopen(h.Identity)
			if mode != "committed" {
				if e == nil || next != nil || h.Disposition != "PENDING" {
					t.Fatal("ASSERT_PENDING_REOPEN_REFUSED")
				}
				t.Log("ASSERT_OBSERVE_CONFIRMATION_BEFORE_RELEASE: PASS")
				return
			}
			if e != nil || next == nil || h.Disposition != "OBSERVED" {
				t.Fatalf("ASSERT_EXPLICIT_VERIFIED_REOPEN: %v %+v", e, h)
			}
			typedAssertRefusedV2(t, next, op, q, context.Background())
			op2, e := next.Reserve(context.Background(), q2)
			if e != nil {
				t.Fatal(e)
			}
			result, obs2, f := next.Execute(context.Background(), op2, q2)
			if f != nil || len(result) == 0 {
				t.Fatalf("ASSERT_NEW_PAID_ATTEMPT: %v", f)
			}
			verify := &kernelV2{root: root}
			final, e := verify.reopen(context.Background(), x.j, next.limits)
			if e != nil {
				t.Fatal(e)
			}
			if final.Windows != 2 || final.Charged.Calls != 2*h.Charged.Calls || final.Charged.ReadHashBytes != 2*h.Charged.ReadHashBytes || !obs2.Checked {
				t.Fatalf("ASSERT_NEW_TRANCHE_NO_REFUND: %+v", final)
			}
			t.Logf("ASSERT_EXPLICIT_VERIFIED_REOPEN: PASS selected=%s disposition=%s previous_calls=%d new_calls=%d old_operation_retired=true", h.Identity, h.Disposition, h.Charged.Calls, final.Charged.Calls)
			t.Log("ASSERT_OBSERVE_CONFIRMATION_BEFORE_RELEASE: PASS")
		})
	}
}
func TestPrivateTypedOwnerConcurrentV2(t *testing.T) {
	o, x := controlledTypedOwnerV2(t)
	q := typedBindingV2(t, x.h.Identity)
	var wg sync.WaitGroup
	ops := make(chan PrivateTypedBundleOperationV2, 2)
	for i := 0; i < 2; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			r := q
			r.Attempt = hashLabelV2(fmt.Sprint(i))
			op, e := o.Reserve(context.Background(), r)
			if e == nil {
				ops <- op
			}
		}(i)
	}
	wg.Wait()
	close(ops)
	var op PrivateTypedBundleOperationV2
	n := 0
	for v := range ops {
		op = v
		n++
	}
	if n != 1 {
		t.Fatalf("ASSERT_ONE_RESERVATION_WINNER: %d", n)
	}
	q.Attempt = op.state.attempt
	results := make(chan bool, 2)
	for i := 0; i < 2; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			b, obs, f := o.Execute(context.Background(), op, q)
			results <- f == nil && len(b) > 0 && obs.Imported && obs.Executed && obs.Checked
		}()
	}
	wg.Wait()
	close(results)
	wins := 0
	for v := range results {
		if v {
			wins++
		}
	}
	if wins != 1 {
		t.Fatalf("ASSERT_SHARED_RETIREMENT_ONE_EXECUTION: wins=%d", wins)
	}
	t.Log("ASSERT_SHARED_RETIREMENT_ONE_EXECUTION: PASS")
}

// The original TestPrivateTypedOwnerObserveUncertaintyRootV2 source and RED log
// are preserved in typed-owner-3khugszu/owned-source and root-uncertainty-red.jsonl.
// Parent explicitly corrected its overstrong permanent-root-poison requirement;
// TestPrivateTypedOwnerObserveFaultV2 now exercises actual work, sticky owner stop,
// close + fresh publication.Root + exact verified reopen, and a NEW charged attempt.
func TestPrivateTypedOwnerExactChargeV2(t *testing.T) {
	got, e := privateTypedBundleChargeV2(time.Unix(10, 0), time.Unix(70, 0))
	if e != nil {
		t.Fatal(e)
	}
	// Preserve the historical observation allowance as reserved logical credits,
	// not measured method calls. All 14 coordinates and funding fixtures remain unchanged.
	want := countersFromV2([14]uint64{43490738368, 43759173824, 2359296, 16812032, 43759173824, 0, 0, 120800231616, 61000000000, 16894464, 67108865, 67174402, 134283267, 67108864})
	if got != want {
		t.Fatalf("ASSERT_COMPLETE_14_CURRENCY_VECTOR: got=%+v want=%+v", got, want)
	}
	t.Logf("ASSERT_COMPLETE_14_CURRENCY_VECTOR: PASS %+v", got)
}

func TestPrivateTypedOwnerReopenBoundaryV2(t *testing.T) {
	_, x := controlledTypedOwnerV2(t)
	l := PrivateManagedInputVerificationV2{4096, 64 << 20, 16384}
	job := sealTestV2(t, &x.j)
	for _, name := range []string{"missing-root", "bad-job", "wrong-selected-head", "corrupt-selected-head"} {
		t.Run(name, func(t *testing.T) {
			root := x.k.root
			raw := bytes.Clone(job)
			head := x.h.Identity
			switch name {
			case "missing-root":
				root = nil
			case "bad-job":
				raw[len(raw)-2] ^= 1
			case "wrong-selected-head":
				head = hashLabelV2("not-the-selected-head")
			case "corrupt-selected-head":
				p := filepath.Join(root.Path(), filepath.FromSlash(currentSelectorV2(x.j)))
				if e := os.WriteFile(p, []byte("corrupt\n"), 0600); e != nil {
					t.Fatal(e)
				}
			}
			if o, e := OpenPrivateTypedBundleOwnerV2(context.Background(), root, raw, head, l); e == nil || o != nil {
				t.Fatal("ASSERT_EXACT_CANONICAL_REOPEN_BOUNDARY")
			}
		})
	}
}
